using System.Text.Json.Nodes;
using MLPlatform.ControlPlane.Application.Common;

namespace MLPlatform.Api.Http.OpenApi;

/// <summary>Serves the OpenAPI document generated by DocGen: the full API to signed-in users, the inference gateway to
/// everyone.</summary>
public static class OpenApiEndpoints
{
    private const string Resource = "openapi.json";
    private const string GatewayPrefix = "/v1/deployments/";
    private static readonly Lazy<string> Full = new(ReadEmbedded);
    private static readonly Lazy<string> Gateway = new(() => GatewayOnly(Full.Value));

    public static void MapOpenApi(this IEndpointRouteBuilder app)
    {
        app.MapGet("/openapi/v1.json", (CurrentUser user) =>
            user.UserId is null ? Results.StatusCode(401) : Results.Text(Full.Value, "application/json"));
        app.MapGet("/openapi/gateway.json", () => Results.Text(Gateway.Value, "application/json"));
    }

    private static string ReadEmbedded()
    {
        using var stream = typeof(OpenApiEndpoints).Assembly.GetManifestResourceStream(Resource)
                           ?? throw new InvalidOperationException("openapi.json is not embedded; run DocGen");
        using var reader = new StreamReader(stream);
        return reader.ReadToEnd();
    }

    private static string GatewayOnly(string full)
    {
        var doc = JsonNode.Parse(full)!.AsObject();
        var paths = doc["paths"]!.AsObject();
        foreach (var path in paths.Select(p => p.Key).Where(p => !p.StartsWith(GatewayPrefix, StringComparison.Ordinal)).ToList()) paths.Remove(path);
        doc["components"]!["schemas"] = new JsonObject();
        return doc.ToJsonString();
    }
}
